function CommonGoodsConsumeNode:RefreshUI(reward)
    local env = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodeMBPath)
    if not isNull(env) then
        local goodsId = reward.goodsId
        env:Reload({
            goodsId = reward.goodsId,
            isShowNo = true,
            text = GoodsUtils.GetGoodsText(goodsId, reward.goodsNum, 3)
        })
        env:SetClickCallback(function()
            GameUtils.ShowCommonGoodsTipsBoard(self.GoodNode.gameObject, goodsId, true)
        end)

        -- self.TxtNumber.text = GoodsUtils.GetGoodsText(goodsId, reward.goodsNum, 3)
    end
end

